INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_001', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมการขาสัตว์และหัวสัตว์', 'ในฟาร์มแห่งหนึ่งมีไก่และกระต่ายรวมกัน 30 ตัว เมื่อนับขารวมกันได้ 84 ขา อยากทราบว่าในฟาร์มนี้มีกระต่ายทั้งหมดกี่ตัว', '["12 ตัว","18 ตัว","15 ตัว","10 ตัว"]', 0, '1) สมมติให้เป็นไก่ทั้งหมด (ตัวละ 2 ขา) จะมีขา = 30 × 2 = 60 ขา
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_002', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เลขหลักหน่วยของเลขยกกำลัง', 'เลขหลักหน่วยของผลลัพธ์ \( 7^{2026} + 3^{2026} \) มีค่าเท่ากับข้อใด', '["8","0","4","2"]', 0, '1) หาวัฏจักรหลักหน่วยของ \( 7^n \): 7, 9, 3, 1 (ซ้ำทุก 4 ตัว) -> 2026 ÷ 4 เหลือเศษ 2 -> หลักหน่วยคือ 9
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_003', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'มุมระหว่างเข็มนาฬิกา', 'เมื่อเวลา 03:40 น. มุมแหลมระหว่างเข็มสั้นและเข็มยาวของนาฬิกามีขนาดกี่องศา', '["130 องศา","140 องศา","125 องศา","135 องศา"]', 0, '1) เข็มยาวชี้เลข 8 = 40 นาที
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_004', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'โจทย์อัตราการทำงานและท่อน้ำ', 'ท่อน้ำ A เปิดน้ำเข้าถังเต็มใน 4 ชั่วโมง ส่วนท่อน้ำ B เปิดเต็มใน 6 ชั่วโมง ถ้าเปิดท่อ A และ B พร้อมกัน น้ำจะเต็มถังในเวลากี่ชั่วโมง', '["\\( 2\\frac{2}{5} \\) ชั่วโมง (2 ชม. 24 นาที)","5 ชั่วโมง","\\( 2\\frac{1}{2} \\) ชั่วโมง","3 ชั่วโมง"]', 0, '1) ใน 1 ชั่วโมง ท่อ A ได้น้ำ \( \frac{1}{4} \) ถัง, ท่อ B ได้ \( \frac{1}{6} \) ถัง
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_005', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อัตราเร็วเรือพายทวนน้ำ-ตามน้ำ', 'เรือยนต์ลำหนึ่งแล่นตามน้ำได้ระยะทาง 60 กิโลเมตร ในเวลา 2 ชั่วโมง แต่เมื่อแล่นทวนน้ำระยะทางเท่าเดิมกลับใช้เวลา 3 ชั่วโมง อยากทราบว่ากระแสน้ำไหลด้วยความเร็วชั่วโมงละกี่กิโลเมตร', '["5 กิโลเมตรต่อชั่วโมง","25 กิโลเมตรต่อชั่วโมง","10 กิโลเมตรต่อชั่วโมง","3 กิโลเมตรต่อชั่วโมง"]', 0, '1) ความเร็วตามน้ำ (เรือ + น้ำ) = 60 ÷ 2 = 30 km/h
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_006', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'หลักรังนกพิราบและความน่าจะเป็น', 'ในลิ้นชักมีถุงเท้าสีขาว 8 คู่ และสีดำ 6 คู่ ปนกันอยู่ ถ้าหยิบถุงเท้าออกมาในที่มืดโดยไม่มอง จะต้องหยิบอย่างน้อยที่สุดกี่ข้าง จึงจะมั่นใจได้ว่าได้ถุงเท้าสีเดียวกันอย่างน้อย 1 คู่แน่นอน', '["3 ข้าง","15 ข้าง","2 ข้าง","8 ข้าง"]', 0, '1) มีสีทั้งหมด 2 สี (ขาว, ดำ)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_007', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เรขาคณิตและพื้นที่แรเงารูปใบไม้', 'รูปสี่เหลี่ยมจัตุรัสรูปหนึ่งมีความยาวด้านละ 14 เซนติเมตร ภายในมีพื้นที่แรเงารูปใบไม้ที่เกิดจากส่วนโค้งของวงกลมรัศมี 14 เซนติเมตร 2 วงตัดกัน จงหาพื้นที่แรเงารูปใบไม้นี้ (กำหนด \( \pi = \frac{22}{7} \))', '["112 ตารางเซนติเมตร","154 ตารางเซนติเมตร","98 ตารางเซนติเมตร","126 ตารางเซนติเมตร"]', 0, '1) สูตรพื้นที่ใบไม้ในจัตุรัส: \( \text{พื้นที่ใบไม้} = \frac{4}{7} \times r^2 \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_008', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'เศษส่วนซ้อนหลายชั้น', 'ถ้า \( \displaystyle x = 2 + \cfrac{1}{3 + \cfrac{1}{4}} \) จงหาค่าของ \( x \) ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{30}{13} \\)","\\( \\displaystyle \\frac{27}{13} \\)","\\( \\displaystyle \\frac{29}{14} \\)","\\( \\displaystyle \\frac{31}{15} \\)"]', 0, '1) คิดชั้นล่างสุด: \( \displaystyle 3 + \frac{1}{4} = \frac{13}{4} \)
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_009', 'math', 'คณิตศาสตร์', 'Regular', 2, 'แผนภาพเวนน์-ออยเลอร์และเซต', 'นักเรียนห้องหนึ่งมี 40 คน ชอบเล่นฟุตบอล 25 คน ชอบเล่นบาสเกตบอล 20 คน และชอบเล่นทั้งสองอย่าง 12 คน อยากทราบว่ามีนักเรียนที่ไม่ชอบเล่นกีฬาทั้งสองชนิดนี้เลยกี่คน', '["7 คน","5 คน","15 คน","10 คน"]', 0, '1) จำนวนคนที่เล่นกีฬาอย่างน้อย 1 อย่าง = ฟุตบอล + บาส - เล่นทั้งสองอย่าง
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_010', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การนับและการจับมือแข่งขัน', 'ในงานเลี้ยงรุ่นมีเพื่อนมาพบกัน 12 คน ถ้าทุกคนจับมือทักทายกันครบทุกคนคนละหนึ่งครั้ง จะมีการจับมือเกิดขึ้นทั้งหมดกี่ครั้ง', '["66 ครั้ง","132 ครั้ง","72 ครั้ง","144 ครั้ง"]', 0, '1) คนที่ 1 จับมือ 11 คน, คนที่ 2 จับมือ 10 คน ... คนสุดท้ายจับ 0 คน
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_011', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'ร้อยละสารละลายและความเข้มข้น', 'น้ำเกลือเข้มข้น 10% จำนวน 160 กรัม ต้องการเติมเกลือบริสุทธิ์ลงไปอีกกี่กรัมเพื่อให้กลายเป็นน้ำเกลือเข้มข้น 20%', '["20 กรัม","25 กรัม","17 กรัม","30 กรัม"]', 0, 'ใช้น้ำเป็นตัวคงที่: น้ำเดิม 90% = น้ำใหม่ 80% คำนวณหามวลเกลือที่ต้องเติม', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["ร้อยละสารละลายและความเข้มข้น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_012', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก', 'จงหาค่าของ \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + ... + \frac{1}{12 \times 13} \)', '["\\( \\displaystyle \\frac{12}{13} \\)","\\( \\displaystyle \\frac{11}{13} \\)","\\( \\displaystyle \\frac{13}{14} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: (1 - 1/2) + (1/2 - 1/3) + ... + (1/12 - 1/13) = 1 - 1/13 = 12/13', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["อนุกรมเศษส่วนเทเลสโคปิก","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_013', 'math', 'คณิตศาสตร์', 'Gifted', 2, 'พีทาโกรัสและสามเหลี่ยมมุมฉาก', 'สามเหลี่ยมมุมฉากรูปหนึ่งมีด้านประกอบมุมฉากยาว 12 ซม. และ 16 ซม. ด้านตรงข้ามมุมฉากจะยาวกี่เซนติเมตร', '["20 เซนติเมตร","22 เซนติเมตร","19 เซนติเมตร","24 เซนติเมตร"]', 0, 'ใช้ทฤษฎีบทพีทาโกรัส อัตราส่วนสามเหลี่ยม 3 : 4 : 5 -> ด้านตรงข้ามมุมฉาก = 5 × 4 = 20 ซม.', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["พีทาโกรัสและสามเหลี่ยมมุมฉาก","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_014', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'การหา ห.ร.ม. และ ค.ร.น. เศษส่วน', 'จงหา ค.ร.น. ของเศษส่วน \( \frac{4}{2}, \frac{8}{3}, \frac{12}{4} \)', '["24","12","48","\\( \\frac{24}{12} \\)"]', 0, 'สูตร ค.ร.น. เศษส่วน = (ค.ร.น. ของเศษ) ÷ (ห.ร.ม. ของส่วน) = (24) ÷ 1 = 24', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["การหา ห.ร.ม. และ ค.ร.น. เศษส่วน","Gifted"]');
