INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_018', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'การหา ห.ร.ม. และ ค.ร.น. เศษส่วน', 'จงหา ค.ร.น. ของเศษส่วน \( \frac{5}{2}, \frac{10}{3}, \frac{15}{4} \)', '["30","15","60","\\( \\frac{30}{12} \\)"]', 0, 'สูตร ค.ร.น. เศษส่วน = (ค.ร.น. ของเศษ) ÷ (ห.ร.ม. ของส่วน) = (30) ÷ 1 = 30', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["การหา ห.ร.ม. และ ค.ร.น. เศษส่วน","Gifted"]');
