INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('m_020', 'math', 'คณิตศาสตร์', 'Gifted', 3, 'อนุกรมเศษส่วนเทเลสโคปิก', 'จงหาค่าของ \( \displaystyle \frac{1}{1 \times 2} + \frac{1}{2 \times 3} + ... + \frac{1}{14 \times 15} \)', '["\\( \\displaystyle \\frac{14}{15} \\)","\\( \\displaystyle \\frac{13}{15} \\)","\\( \\displaystyle \\frac{15}{16} \\)","1"]', 0, 'แยกเศษส่วนย่อยตัดกัน: (1 - 1/2) + (1/2 - 1/3) + ... + (1/14 - 1/15) = 1 - 1/15 = 14/15', 'คิดตามหลักการและสูตรลัด', 'วิเคราะห์ทีละขั้นตอน', '["อนุกรมเศษส่วนเทเลสโคปิก","Gifted"]');
