INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_035', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ตอนที่ 35)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างครึ่งดวงด้านใด และจะขึ้นจากขอบฟ้าเวลาประมาณเท่าใด (ข้อสอบชุดที่ 35)', '["สว่างครึ่งดวงทางทิศตะวันออก (หันด้านสว่างไปทางซ้าย) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงทางทิศตะวันตก และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง และขึ้นเวลา 18:00 น.","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์จะค่อยๆ แหว่งจากขวาไปซ้าย สว่างซีกซ้าย (ตะวันออก) และขึ้นหลังเที่ยงคืน', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ดาราศาสตร์: เฟสดวงจันทร์ (ตอนที่ 35)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_036', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบความเป็นกรด-เบส (ตอนที่ 36)', 'สารละลายชนิดหนึ่งเปลี่ยนสีกระดาษลิตมัสจากสีแดงเป็นสีน้ำเงิน และเมื่อหยดฟีนอล์ฟทาลีนลงไปจะเปลี่ยนเป็นสีชมพู สารนี้น่าจะเป็นสารใด (ข้อสอบชุดที่ 36)', '["น้ำสบู่ หรือ น้ำขี้เถ้า (สารละลายเบส)","น้ำมะนาว หรือ น้ำส้มสายชู (กรด)","น้ำเกลือบริสุทธิ์ (กลาง)","น้ำกลั่นบริสุทธิ์"]', 0, 'สารละลายเบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["เคมี: การทดสอบความเป็นกรด-เบส (ตอนที่ 36)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_037', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ตอนที่ 37)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้ผิวโลกเป็นเวลานาน จะแปรสภาพกลายเป็นหินชนิดใด (ข้อสอบชุดที่ 37)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรสภาพเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ธรณีวิทยา: วัฏจักรของหิน (ตอนที่ 37)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_038', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ฟิสิกส์: การถ่ายโอนความร้อน (ตอนที่ 38)', 'การส่งผ่านความร้อนจากดวงอาทิตย์มายังโลกผ่านอวกาศที่ไม่มีโมเลกุลของตัวกลาง เป็นการถ่ายโอนความร้อนแบบใด (ข้อสอบชุดที่ 38)', '["การแผ่รังสีความร้อน (Radiation)","การพาความร้อน (Convection)","การนำความร้อน (Conduction)","การแทรกสอดความร้อน"]', 0, 'การแผ่รังสีความร้อนเป็นวิธีเดียวที่เดินทางผ่านสุญญากาศได้โดยไม่ต้องอาศัยตัวกลาง', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ฟิสิกส์: การถ่ายโอนความร้อน (ตอนที่ 38)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_039', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'นิเวศวิทยา: ภาวะความสัมพันธ์ (ตอนที่ 39)', 'ความสัมพันธ์ระหว่าง ผึ้งกับดอกไม้ และ กล้วยไม้บนต้นไม้ใหญ่ จัดเป็นภาวะความสัมพันธ์แบบใดตามลำดับ (ข้อสอบชุดที่ 39)', '["ภาวะได้ประโยชน์ร่วมกัน (+/+) และ ภาวะอิงอาศัย (+/0)","ภาวะพึ่งพากัน และ ภาวะปรสิต","ภาวะล่าเหยื่อ และ ภาวะได้ประโยชน์ร่วมกัน","ภาวะอิงอาศัยทั้งสองคู่"]', 0, 'ผึ้งได้น้ำหวาน ดอกไม้ได้ผสมเกสร (+/+) ส่วนกล้วยไม้อาศัยเกาะต้นไม้โดยไม่แย่งอาหาร (+/0)', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["นิเวศวิทยา: ภาวะความสัมพันธ์ (ตอนที่ 39)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_040', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: กระจกและเลนส์ (ตอนที่ 40)', 'กระจกชนิดใดที่ติดตั้งตามมุมทางแยกหรือกระจกมองข้างรถยนต์ เพื่อช่วยให้มองเห็นมุมมองภาพที่กว้างขึ้น (ข้อสอบชุดที่ 40)', '["กระจกนูน (Convex Mirror)","กระจกเว้า (Concave Mirror)","กระจกเงาราบ (Plane Mirror)","เลนส์เว้า"]', 0, 'กระจกนูนให้ภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุ ทำให้มีขอบเขตลานสายตากว้างขึ้น', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ฟิสิกส์: กระจกและเลนส์ (ตอนที่ 40)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_041', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'การทดสอบสารอาหารและอินดิเคเตอร์ (ตอนที่ 41)', 'เมื่อหยดสารละลายเบเนดิกต์ลงในสารละลายตัวอย่างแล้วนำไปต้มในน้ำเดือด เกิดตะกอนสีส้มอิฐ แสดงว่าสารตัวอย่างมีสารอาหารใด (ข้อสอบชุดที่ 41)', '["น้ำตาลโมเลกุลเดี่ยว (เช่น กลูโคส ฟรักโทส)","แป้งและคาร์โบไฮเดรตเชิงซ้อน","โปรตีนและกรดอะมิโน","ไขมันและน้ำมัน"]', 0, 'สารละลายเบเนดิกต์ทำปฏิกิริยากับน้ำตาลรีดิวซ์เกิดตะกอนสีแดงอิฐเมื่อต้ม', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["การทดสอบสารอาหารและอินดิเคเตอร์ (ตอนที่ 41)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_042', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ชีววิทยาของพืช: ท่อลำเลียง (ตอนที่ 42)', 'ท่อลำเลียง โฟลเอ็ม (Phloem) ในพืชทำหน้าที่ลำเลียงสิ่งใดและมีทิศทางการลำเลียงอย่างไร (ข้อสอบชุดที่ 42)', '["ลำเลียงอาหาร (น้ำตาล) จากใบไปสู่ทุกส่วนของพืชได้ทุกทิศทาง","ลำเลียงน้ำและแร่ธาตุจากรากขึ้นสู่ใบทางเดียว","ลำเลียงแก๊สออกซิเจน","ลำเลียงฮอร์โมนจากดอกไปรากเท่านั้น"]', 0, 'ไซเลมลำเลียงน้ำจากล่างขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทั้งขึ้นและลง', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ชีววิทยาของพืช: ท่อลำเลียง (ตอนที่ 42)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_043', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'พันธุศาสตร์และหมู่เลือด ABO (ตอนที่ 43)', 'พ่อมีเลือดหมู่ A (Genotype: IA i) และแม่มีเลือดหมู่ B (Genotype: IB i) ลูกที่เกิดมามีโอกาสมีเลือดหมู่ใดได้บ้าง (ข้อสอบชุดที่ 43)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O) ในอัตราส่วน 1:1:1:1","มีโอกาสเป็นเฉพาะหมู่ AB เท่านั้น","มีโอกาสเป็นเฉพาะหมู่ A และ B","มีโอกาสเป็นหมู่ A, B, AB แต่ไม่มีทางเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA กับ IB, IA กับ i, IB กับ i, และ i กับ i ทำให้เกิดหมู่ AB, A, B, O ได้ครบ', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["พันธุศาสตร์และหมู่เลือด ABO (ตอนที่ 43)","Regular"]');
