INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_095', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์: เฟสดวงจันทร์ (ตอนที่ 95)', 'ในวัน แรม 8 ค่ำ ดวงจันทร์จะปรากฏสว่างครึ่งดวงด้านใด และจะขึ้นจากขอบฟ้าเวลาประมาณเท่าใด (ข้อสอบชุดที่ 95)', '["สว่างครึ่งดวงทางทิศตะวันออก (หันด้านสว่างไปทางซ้าย) และขึ้นเวลาเที่ยงคืน","สว่างครึ่งดวงทางทิศตะวันตก และขึ้นเวลาเที่ยงวัน","สว่างเต็มดวง และขึ้นเวลา 18:00 น.","มืดสนิททั้งดวง"]', 0, 'ข้างแรมดวงจันทร์จะค่อยๆ แหว่งจากขวาไปซ้าย สว่างซีกซ้าย (ตะวันออก) และขึ้นหลังเที่ยงคืน', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ดาราศาสตร์: เฟสดวงจันทร์ (ตอนที่ 95)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_096', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'เคมี: การทดสอบความเป็นกรด-เบส (ตอนที่ 96)', 'สารละลายชนิดหนึ่งเปลี่ยนสีกระดาษลิตมัสจากสีแดงเป็นสีน้ำเงิน และเมื่อหยดฟีนอล์ฟทาลีนลงไปจะเปลี่ยนเป็นสีชมพู สารนี้น่าจะเป็นสารใด (ข้อสอบชุดที่ 96)', '["น้ำสบู่ หรือ น้ำขี้เถ้า (สารละลายเบส)","น้ำมะนาว หรือ น้ำส้มสายชู (กรด)","น้ำเกลือบริสุทธิ์ (กลาง)","น้ำกลั่นบริสุทธิ์"]', 0, 'สารละลายเบสเปลี่ยนลิตมัสแดงเป็นน้ำเงิน และทำให้ฟีนอล์ฟทาลีนเปลี่ยนเป็นสีชมพู', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["เคมี: การทดสอบความเป็นกรด-เบส (ตอนที่ 96)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_097', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ธรณีวิทยา: วัฏจักรของหิน (ตอนที่ 97)', 'หินแกรนิตเมื่อถูกความร้อนและความดันสูงใต้ผิวโลกเป็นเวลานาน จะแปรสภาพกลายเป็นหินชนิดใด (ข้อสอบชุดที่ 97)', '["หินไนส์ (Gneiss)","หินอ่อน","หินชนวน","หินควอร์ตไซต์"]', 0, 'หินแกรนิต (อัคนี) แปรสภาพเป็นหินไนส์ ส่วนหินปูนแปรเป็นหินอ่อน', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ธรณีวิทยา: วัฏจักรของหิน (ตอนที่ 97)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_098', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ฟิสิกส์: การถ่ายโอนความร้อน (ตอนที่ 98)', 'การส่งผ่านความร้อนจากดวงอาทิตย์มายังโลกผ่านอวกาศที่ไม่มีโมเลกุลของตัวกลาง เป็นการถ่ายโอนความร้อนแบบใด (ข้อสอบชุดที่ 98)', '["การแผ่รังสีความร้อน (Radiation)","การพาความร้อน (Convection)","การนำความร้อน (Conduction)","การแทรกสอดความร้อน"]', 0, 'การแผ่รังสีความร้อนเป็นวิธีเดียวที่เดินทางผ่านสุญญากาศได้โดยไม่ต้องอาศัยตัวกลาง', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ฟิสิกส์: การถ่ายโอนความร้อน (ตอนที่ 98)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_099', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'นิเวศวิทยา: ภาวะความสัมพันธ์ (ตอนที่ 99)', 'ความสัมพันธ์ระหว่าง ผึ้งกับดอกไม้ และ กล้วยไม้บนต้นไม้ใหญ่ จัดเป็นภาวะความสัมพันธ์แบบใดตามลำดับ (ข้อสอบชุดที่ 99)', '["ภาวะได้ประโยชน์ร่วมกัน (+/+) และ ภาวะอิงอาศัย (+/0)","ภาวะพึ่งพากัน และ ภาวะปรสิต","ภาวะล่าเหยื่อ และ ภาวะได้ประโยชน์ร่วมกัน","ภาวะอิงอาศัยทั้งสองคู่"]', 0, 'ผึ้งได้น้ำหวาน ดอกไม้ได้ผสมเกสร (+/+) ส่วนกล้วยไม้อาศัยเกาะต้นไม้โดยไม่แย่งอาหาร (+/0)', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["นิเวศวิทยา: ภาวะความสัมพันธ์ (ตอนที่ 99)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_100', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ฟิสิกส์: กระจกและเลนส์ (ตอนที่ 100)', 'กระจกชนิดใดที่ติดตั้งตามมุมทางแยกหรือกระจกมองข้างรถยนต์ เพื่อช่วยให้มองเห็นมุมมองภาพที่กว้างขึ้น (ข้อสอบชุดที่ 100)', '["กระจกนูน (Convex Mirror)","กระจกเว้า (Concave Mirror)","กระจกเงาราบ (Plane Mirror)","เลนส์เว้า"]', 0, 'กระจกนูนให้ภาพเสมือนหัวตั้งขนาดเล็กกว่าวัตถุ ทำให้มีขอบเขตลานสายตากว้างขึ้น', 'อ่านคำถามและวิเคราะห์สมมติฐาน', 'จำหลักการทางวิทยาศาสตร์', '["ฟิสิกส์: กระจกและเลนส์ (ตอนที่ 100)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_001', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subjunctive / Wish Clauses (Part 1)', 'I wish I ______ enough money to buy that smart tablet right now. (Question 1)', '["had","have","will have","have had"]', 0, 'โครงสร้าง Wish ในปัจจุบันใช้ Past Simple (V.2) เพื่อแสดงความปรารถนาที่ตรงข้ามกับความจริง', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Subjunctive / Wish Clauses (Part 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_002', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Phrasal Verbs (Part 2)', 'Can you please ______ my cat while I am away on vacation this weekend? (Question 2)', '["look after","look for","look into","look up"]', 0, 'look after แปลว่า ดูแลเอาใจใส่, look for = มองหา, look up = ค้นหาคำศัพท์', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Phrasal Verbs (Part 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_003', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Gerund vs Infinitive (Part 3)', 'My sister decided ______ medicine at Chulalongkorn University next year. (Question 3)', '["to study","studying","study","studied"]', 0, 'decide ตามด้วย to + V.inf เสมอ (decide to do something)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Gerund vs Infinitive (Part 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_004', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Quantifiers (Few vs Little) (Part 4)', 'There is very ______ milk left in the fridge, so we need to buy more. (Question 4)', '["little","few","a few","many"]', 0, 'milk เป็นนามนับไม่ได้และมีปริมาณน้อยมากจนแทบไม่มี ใช้ little', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Quantifiers (Few vs Little) (Part 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_005', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Dependent Prepositions (Part 5)', 'Teacher Lisa is famous ______ her creative English teaching techniques. (Question 5)', '["for","with","in","at"]', 0, 'famous คู่กับบุพบท for เสมอ (famous for = มีชื่อเสียงในด้าน)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Dependent Prepositions (Part 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_006', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms & Expressions (Part 6)', 'The math quiz was a ______! I finished all 20 questions in 10 minutes. (Question 6)', '["piece of cake","cup of tea","spill the beans","cold feet"]', 0, 'a piece of cake เป็นสำนวนหมายถึง ง่ายมากๆ (very easy)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Idioms & Expressions (Part 6)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_007', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Contrast) (Part 7)', '______ it rained heavily this morning, all students arrived at school on time. (Question 7)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่ขัดแย้งกัน ตามด้วยประธาน + กริยา', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Conjunctions (Contrast) (Part 7)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_008', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Reported Speech (Part 8)', 'Tom told me, "I am studying math." -> Tom told me that he ______ math. (Question 8)', '["was studying","is studying","studied","had studied"]', 0, 'เปลี่ยน Present Continuous (am studying) เป็น Past Continuous (was studying)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Reported Speech (Part 8)","Gifted"]');
