INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_022', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Phrasal Verbs (Part 22)', 'Can you please ______ my cat while I am away on vacation this weekend? (Question 22)', '["look after","look for","look into","look up"]', 0, 'look after แปลว่า ดูแลเอาใจใส่, look for = มองหา, look up = ค้นหาคำศัพท์', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Phrasal Verbs (Part 22)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_023', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Gerund vs Infinitive (Part 23)', 'My sister decided ______ medicine at Chulalongkorn University next year. (Question 23)', '["to study","studying","study","studied"]', 0, 'decide ตามด้วย to + V.inf เสมอ (decide to do something)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Gerund vs Infinitive (Part 23)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_024', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Quantifiers (Few vs Little) (Part 24)', 'There is very ______ milk left in the fridge, so we need to buy more. (Question 24)', '["little","few","a few","many"]', 0, 'milk เป็นนามนับไม่ได้และมีปริมาณน้อยมากจนแทบไม่มี ใช้ little', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Quantifiers (Few vs Little) (Part 24)","Gifted"]');
