INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_026', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Idioms & Expressions (Part 26)', 'The math quiz was a ______! I finished all 20 questions in 10 minutes. (Question 26)', '["piece of cake","cup of tea","spill the beans","cold feet"]', 0, 'a piece of cake เป็นสำนวนหมายถึง ง่ายมากๆ (very easy)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Idioms & Expressions (Part 26)","Gifted"]');
