INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_059', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Modal Auxiliaries (Part 59)', 'You ______ wear a seatbelt while driving. It is the law in Thailand. (Question 59)', '["must","might","should","could"]', 0, 'must ใช้กับกฎหมายหรือข้อบังคับที่จำเป็นต้องทำ 100%', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Modal Auxiliaries (Part 59)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_060', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Articles (A/An/The) (Part 60)', 'My uncle is ______ honest police officer who works in Bangkok. (Question 60)', '["an","a","the","no article"]', 0, 'คำว่า honest ออกเสียงสระ อ- (ออน-เนิสท์) จึงต้องใช้คำนำหน้าว่า an', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Articles (A/An/The) (Part 60)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_061', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subjunctive / Wish Clauses (Part 61)', 'I wish I ______ enough money to buy that smart tablet right now. (Question 61)', '["had","have","will have","have had"]', 0, 'โครงสร้าง Wish ในปัจจุบันใช้ Past Simple (V.2) เพื่อแสดงความปรารถนาที่ตรงข้ามกับความจริง', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Subjunctive / Wish Clauses (Part 61)","Regular"]');
