INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_096', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Idioms & Expressions (Part 96)', 'The math quiz was a ______! I finished all 20 questions in 10 minutes. (Question 96)', '["piece of cake","cup of tea","spill the beans","cold feet"]', 0, 'a piece of cake เป็นสำนวนหมายถึง ง่ายมากๆ (very easy)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Idioms & Expressions (Part 96)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_097', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Conjunctions (Contrast) (Part 97)', '______ it rained heavily this morning, all students arrived at school on time. (Question 97)', '["Although","Because","Therefore","Despite of"]', 0, 'Although (แม้ว่า) ใช้เชื่อมประโยคที่ขัดแย้งกัน ตามด้วยประธาน + กริยา', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Conjunctions (Contrast) (Part 97)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_098', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Reported Speech (Part 98)', 'Tom told me, "I am studying math." -> Tom told me that he ______ math. (Question 98)', '["was studying","is studying","studied","had studied"]', 0, 'เปลี่ยน Present Continuous (am studying) เป็น Past Continuous (was studying)', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Reported Speech (Part 98)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_099', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Modal Auxiliaries (Part 99)', 'You ______ wear a seatbelt while driving. It is the law in Thailand. (Question 99)', '["must","might","should","could"]', 0, 'must ใช้กับกฎหมายหรือข้อบังคับที่จำเป็นต้องทำ 100%', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Modal Auxiliaries (Part 99)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_100', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Articles (A/An/The) (Part 100)', 'My uncle is ______ honest police officer who works in Bangkok. (Question 100)', '["an","a","the","no article"]', 0, 'คำว่า honest ออกเสียงสระ อ- (ออน-เนิสท์) จึงต้องใช้คำนำหน้าว่า an', 'Check grammatical rules and keywords', 'Identify the key trigger word', '["Articles (A/An/The) (Part 100)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_001', 'thai', 'ภาษาไทย', 'Regular', 2, 'บาลี vs สันสกฤต (หมวดที่ 1)', 'ข้อใดประกอบด้วยคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อที่ 1)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี, สัจจะ","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร เช่น กษัตริย์ ศรัทธา ปรัชญา', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["บาลี vs สันสกฤต (หมวดที่ 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_002', 'thai', 'ภาษาไทย', 'Gifted', 3, 'โวหารภาพพจน์ในวรรณคดี (หมวดที่ 2)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ข้อความนี้ใช้โวหารภาพพจน์ประเภทใด (ข้อที่ 2)', '["อุปมา (Simile - การเปรียบเทียบว่าเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น/คือ)","บุคลาธิษฐาน (Personification)","สัทพจน์ (Onomatopoeia)"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["โวหารภาพพจน์ในวรรณคดี (หมวดที่ 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_003', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำซ้อนเพื่อความหมาย vs เพื่อเสียง (หมวดที่ 3)', 'ข้อใดเป็น คำซ้อนเพื่อเสียง ทุกคำ (ข้อที่ 3)', '["ตูมตาม, ซุบซิบ, งงงวย, ออดแอด","บ้านเรือน, เสื้อผ้า, จิตใจ","ยากง่าย, เท็จจริง, ดีชั่ว","แม่น้ำ, รถไฟ, น้ำปลา"]', 0, 'ตูมตาม ซุบซิบ งงงวย เป็นคำซ้อนที่เน้นจังหวะเสียงสัมผัสเพื่อความไพเราะ', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำซ้อนเพื่อความหมาย vs เพื่อเสียง (หมวดที่ 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_004', 'thai', 'ภาษาไทย', 'Gifted', 2, 'ประโยคเพื่อการสื่อสาร (หมวดที่ 4)', '"กรุณาถอดรองเท้าก่อนเข้าห้องสมุด" จัดเป็นประโยคชนิดใดตามเจตนาการสื่อสาร (ข้อที่ 4)', '["ประโยคขอร้อง","ประโยคคำสั่ง","ประโยคบอกเล่า","ประโยคเงื่อนไข"]', 0, 'มีคำว่า กรุณา, โปรด, วาน แสดงเจตนาขอร้องอย่างสุภาพ', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["ประโยคเพื่อการสื่อสาร (หมวดที่ 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_005', 'thai', 'ภาษาไทย', 'Regular', 3, 'การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 5)', 'คำว่า "ไม้" มีรูปและเสียงวรรณยุกต์ตรงกับข้อใด (ข้อที่ 5)', '["รูปโท แต่เสียงตรี","รูปโท เสียงโท","รูปเอก เสียงโท","รูปตรี เสียงตรี"]', 0, 'อักษรต่ำ (ม) เมื่อใส่ไม้โท จะผันเป็นเสียงตรี', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_006', 'thai', 'ภาษาไทย', 'Gifted', 1, 'สำนวนไทยจากวรรณคดี (หมวดที่ 6)', 'สำนวนใดมีที่มาจากวรรณคดีเรื่อง ขุนช้างขุนแผน (ข้อที่ 6)', '["ว่าแต่เขาอิเหนาเป็นเอง หรือ ลูกทรพี","กบในกะลาครอบ","จับปลาสองมือ","ไก่เห็นตีนงู"]', 0, 'ลูกทรพีมาจากเรื่องรามเกียรติ์/ขุนช้างขุนแผนสื่อถึงตัวละคร', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["สำนวนไทยจากวรรณคดี (หมวดที่ 6)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_007', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำพ้องรูป vs พ้องเสียง (หมวดที่ 7)', 'คำคู่ใดจัดเป็น คำพ้องรูป (เขียนเหมือนกันแต่อ่านต่างกันและคนละความหมาย) (ข้อที่ 7)', '["เพลา (เพ-ลา / เพลา), เพชรบุรี (เพ็ด-ชะ-บุ-รี / สระ-เพ็ด)","การ / กาล / กานต์","บาท / บาตร / บาตร","ขัน / ขัน / ขัน"]', 0, 'เพลา อ่านได้ทั้ง เพ-ลา (เวลา) และ เพลา (เบาลง/เพลารถ)', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำพ้องรูป vs พ้องเสียง (หมวดที่ 7)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_008', 'thai', 'ภาษาไทย', 'Gifted', 3, 'คำราชาศัพท์หมวดร่างกาย (หมวดที่ 8)', 'คำราชาศัพท์ของ "หน้าผาก" และ "หัวเข่า" คือข้อใดตามลำดับ (ข้อที่ 8)', '["พระนลาฏ, พระชานุ","พระขนง, พระอุระ","พระกรรณ, พระบาท","พระหัตถ์, พระศอ"]', 0, 'พระนลาฏ = หน้าผาก, พระชานุ = หัวเข่า, พระขนง = คิ้ว', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำราชาศัพท์หมวดร่างกาย (หมวดที่ 8)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_009', 'thai', 'ภาษาไทย', 'Regular', 1, 'ชนิดของคำ: คำสรรพนาม (หมวดที่ 9)', 'ในประโยค "นักเรียนต่างคนต่างช่วยกันทำความสะอาดห้องเรียน" คำว่า "ต่าง" ทำหน้าที่เป็นคำสรรพนามชนิดใด (ข้อที่ 9)', '["วิภาคสรรพนาม (สรรพนามแยกฝ่าย)","นิยมสรรพนาม (ชี้เฉพาะ)","อนิยมสรรพนาม","ประพันธสรรพนาม"]', 0, 'คำว่า ต่าง, บ้าง, กัน ที่ใช้แยกฝ่ายหรือแสดงกริยาร่วมกันเป็นวิภาคสรรพนาม', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["ชนิดของคำ: คำสรรพนาม (หมวดที่ 9)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_010', 'thai', 'ภาษาไทย', 'Gifted', 2, 'การใช้ระดับภาษา (หมวดที่ 10)', 'ข้อความใดใช้ภาษา ระดับทางการ ได้อย่างถูกต้องเหมาะสมที่สุด (ข้อที่ 10)', '["โรงเรียนขอเชิญผู้ปกครองเข้าร่วมการประชุมใหญ่สามัญประจำปี","คุณพ่อคุณแม่รีบๆ มาคุยกันที่โรงเรียนนะ","พวกเราจัดงานประชุมใหญ่โตมากเชิญมาดู","ขอให้ทุกคนมาพร้อมหน้าพร้อมตากันที่โรงเรียน"]', 0, 'ใช้ถ้อยคำสุภาพ แบบแผน เป็นทางการและกะทัดรัด', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การใช้ระดับภาษา (หมวดที่ 10)","Gifted"]');
