INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_015', 'thai', 'ภาษาไทย', 'Regular', 1, 'การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 15)', 'คำว่า "ไม้" มีรูปและเสียงวรรณยุกต์ตรงกับข้อใด (ข้อที่ 15)', '["รูปโท แต่เสียงตรี","รูปโท เสียงโท","รูปเอก เสียงโท","รูปตรี เสียงตรี"]', 0, 'อักษรต่ำ (ม) เมื่อใส่ไม้โท จะผันเป็นเสียงตรี', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 15)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_016', 'thai', 'ภาษาไทย', 'Gifted', 2, 'สำนวนไทยจากวรรณคดี (หมวดที่ 16)', 'สำนวนใดมีที่มาจากวรรณคดีเรื่อง ขุนช้างขุนแผน (ข้อที่ 16)', '["ว่าแต่เขาอิเหนาเป็นเอง หรือ ลูกทรพี","กบในกะลาครอบ","จับปลาสองมือ","ไก่เห็นตีนงู"]', 0, 'ลูกทรพีมาจากเรื่องรามเกียรติ์/ขุนช้างขุนแผนสื่อถึงตัวละคร', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["สำนวนไทยจากวรรณคดี (หมวดที่ 16)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_017', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำพ้องรูป vs พ้องเสียง (หมวดที่ 17)', 'คำคู่ใดจัดเป็น คำพ้องรูป (เขียนเหมือนกันแต่อ่านต่างกันและคนละความหมาย) (ข้อที่ 17)', '["เพลา (เพ-ลา / เพลา), เพชรบุรี (เพ็ด-ชะ-บุ-รี / สระ-เพ็ด)","การ / กาล / กานต์","บาท / บาตร / บาตร","ขัน / ขัน / ขัน"]', 0, 'เพลา อ่านได้ทั้ง เพ-ลา (เวลา) และ เพลา (เบาลง/เพลารถ)', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำพ้องรูป vs พ้องเสียง (หมวดที่ 17)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_018', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำราชาศัพท์หมวดร่างกาย (หมวดที่ 18)', 'คำราชาศัพท์ของ "หน้าผาก" และ "หัวเข่า" คือข้อใดตามลำดับ (ข้อที่ 18)', '["พระนลาฏ, พระชานุ","พระขนง, พระอุระ","พระกรรณ, พระบาท","พระหัตถ์, พระศอ"]', 0, 'พระนลาฏ = หน้าผาก, พระชานุ = หัวเข่า, พระขนง = คิ้ว', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำราชาศัพท์หมวดร่างกาย (หมวดที่ 18)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_019', 'thai', 'ภาษาไทย', 'Regular', 2, 'ชนิดของคำ: คำสรรพนาม (หมวดที่ 19)', 'ในประโยค "นักเรียนต่างคนต่างช่วยกันทำความสะอาดห้องเรียน" คำว่า "ต่าง" ทำหน้าที่เป็นคำสรรพนามชนิดใด (ข้อที่ 19)', '["วิภาคสรรพนาม (สรรพนามแยกฝ่าย)","นิยมสรรพนาม (ชี้เฉพาะ)","อนิยมสรรพนาม","ประพันธสรรพนาม"]', 0, 'คำว่า ต่าง, บ้าง, กัน ที่ใช้แยกฝ่ายหรือแสดงกริยาร่วมกันเป็นวิภาคสรรพนาม', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["ชนิดของคำ: คำสรรพนาม (หมวดที่ 19)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_020', 'thai', 'ภาษาไทย', 'Gifted', 3, 'การใช้ระดับภาษา (หมวดที่ 20)', 'ข้อความใดใช้ภาษา ระดับทางการ ได้อย่างถูกต้องเหมาะสมที่สุด (ข้อที่ 20)', '["โรงเรียนขอเชิญผู้ปกครองเข้าร่วมการประชุมใหญ่สามัญประจำปี","คุณพ่อคุณแม่รีบๆ มาคุยกันที่โรงเรียนนะ","พวกเราจัดงานประชุมใหญ่โตมากเชิญมาดู","ขอให้ทุกคนมาพร้อมหน้าพร้อมตากันที่โรงเรียน"]', 0, 'ใช้ถ้อยคำสุภาพ แบบแผน เป็นทางการและกะทัดรัด', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การใช้ระดับภาษา (หมวดที่ 20)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_021', 'thai', 'ภาษาไทย', 'Regular', 1, 'บาลี vs สันสกฤต (หมวดที่ 21)', 'ข้อใดประกอบด้วยคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อที่ 21)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี, สัจจะ","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร เช่น กษัตริย์ ศรัทธา ปรัชญา', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["บาลี vs สันสกฤต (หมวดที่ 21)","Regular"]');
