INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_030', 'thai', 'ภาษาไทย', 'Gifted', 1, 'การใช้ระดับภาษา (หมวดที่ 30)', 'ข้อความใดใช้ภาษา ระดับทางการ ได้อย่างถูกต้องเหมาะสมที่สุด (ข้อที่ 30)', '["โรงเรียนขอเชิญผู้ปกครองเข้าร่วมการประชุมใหญ่สามัญประจำปี","คุณพ่อคุณแม่รีบๆ มาคุยกันที่โรงเรียนนะ","พวกเราจัดงานประชุมใหญ่โตมากเชิญมาดู","ขอให้ทุกคนมาพร้อมหน้าพร้อมตากันที่โรงเรียน"]', 0, 'ใช้ถ้อยคำสุภาพ แบบแผน เป็นทางการและกะทัดรัด', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การใช้ระดับภาษา (หมวดที่ 30)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_031', 'thai', 'ภาษาไทย', 'Regular', 2, 'บาลี vs สันสกฤต (หมวดที่ 31)', 'ข้อใดประกอบด้วยคำยืมที่มาจากภาษา สันสกฤต ทุกคำ (ข้อที่ 31)', '["กษัตริย์, ศรัทธา, วิทยา, ปรัชญา","มัจฉา, ปัญญา, ทัพพี, สัจจะ","เขนย, ฉลอง, บังเอิญ","เก้าอี้, เต้าหู้, โต๊ะ"]', 0, 'สันสกฤตมีตัว ศ, ษ, ฤ, ควบกล้ำ และ รร เช่น กษัตริย์ ศรัทธา ปรัชญา', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["บาลี vs สันสกฤต (หมวดที่ 31)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_032', 'thai', 'ภาษาไทย', 'Gifted', 3, 'โวหารภาพพจน์ในวรรณคดี (หมวดที่ 32)', '"เสียงฟ้าร้องคำรามกึกก้องประหนึ่งเสียงยักษ์ตวาด" ข้อความนี้ใช้โวหารภาพพจน์ประเภทใด (ข้อที่ 32)', '["อุปมา (Simile - การเปรียบเทียบว่าเหมือน)","อุปลักษณ์ (Metaphor - เปรียบเป็น/คือ)","บุคลาธิษฐาน (Personification)","สัทพจน์ (Onomatopoeia)"]', 0, 'มีคำเชื่อมเปรียบเทียบคำว่า ประหนึ่ง จัดเป็น อุปมาโวหาร', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["โวหารภาพพจน์ในวรรณคดี (หมวดที่ 32)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_033', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำซ้อนเพื่อความหมาย vs เพื่อเสียง (หมวดที่ 33)', 'ข้อใดเป็น คำซ้อนเพื่อเสียง ทุกคำ (ข้อที่ 33)', '["ตูมตาม, ซุบซิบ, งงงวย, ออดแอด","บ้านเรือน, เสื้อผ้า, จิตใจ","ยากง่าย, เท็จจริง, ดีชั่ว","แม่น้ำ, รถไฟ, น้ำปลา"]', 0, 'ตูมตาม ซุบซิบ งงงวย เป็นคำซ้อนที่เน้นจังหวะเสียงสัมผัสเพื่อความไพเราะ', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำซ้อนเพื่อความหมาย vs เพื่อเสียง (หมวดที่ 33)","Regular"]');
