INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_075', 'thai', 'ภาษาไทย', 'Regular', 1, 'การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 75)', 'คำว่า "ไม้" มีรูปและเสียงวรรณยุกต์ตรงกับข้อใด (ข้อที่ 75)', '["รูปโท แต่เสียงตรี","รูปโท เสียงโท","รูปเอก เสียงโท","รูปตรี เสียงตรี"]', 0, 'อักษรต่ำ (ม) เมื่อใส่ไม้โท จะผันเป็นเสียงตรี', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การผันวรรณยุกต์อักษรต่ำ (หมวดที่ 75)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_076', 'thai', 'ภาษาไทย', 'Gifted', 2, 'สำนวนไทยจากวรรณคดี (หมวดที่ 76)', 'สำนวนใดมีที่มาจากวรรณคดีเรื่อง ขุนช้างขุนแผน (ข้อที่ 76)', '["ว่าแต่เขาอิเหนาเป็นเอง หรือ ลูกทรพี","กบในกะลาครอบ","จับปลาสองมือ","ไก่เห็นตีนงู"]', 0, 'ลูกทรพีมาจากเรื่องรามเกียรติ์/ขุนช้างขุนแผนสื่อถึงตัวละคร', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["สำนวนไทยจากวรรณคดี (หมวดที่ 76)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_077', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำพ้องรูป vs พ้องเสียง (หมวดที่ 77)', 'คำคู่ใดจัดเป็น คำพ้องรูป (เขียนเหมือนกันแต่อ่านต่างกันและคนละความหมาย) (ข้อที่ 77)', '["เพลา (เพ-ลา / เพลา), เพชรบุรี (เพ็ด-ชะ-บุ-รี / สระ-เพ็ด)","การ / กาล / กานต์","บาท / บาตร / บาตร","ขัน / ขัน / ขัน"]', 0, 'เพลา อ่านได้ทั้ง เพ-ลา (เวลา) และ เพลา (เบาลง/เพลารถ)', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำพ้องรูป vs พ้องเสียง (หมวดที่ 77)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_078', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำราชาศัพท์หมวดร่างกาย (หมวดที่ 78)', 'คำราชาศัพท์ของ "หน้าผาก" และ "หัวเข่า" คือข้อใดตามลำดับ (ข้อที่ 78)', '["พระนลาฏ, พระชานุ","พระขนง, พระอุระ","พระกรรณ, พระบาท","พระหัตถ์, พระศอ"]', 0, 'พระนลาฏ = หน้าผาก, พระชานุ = หัวเข่า, พระขนง = คิ้ว', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["คำราชาศัพท์หมวดร่างกาย (หมวดที่ 78)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_079', 'thai', 'ภาษาไทย', 'Regular', 2, 'ชนิดของคำ: คำสรรพนาม (หมวดที่ 79)', 'ในประโยค "นักเรียนต่างคนต่างช่วยกันทำความสะอาดห้องเรียน" คำว่า "ต่าง" ทำหน้าที่เป็นคำสรรพนามชนิดใด (ข้อที่ 79)', '["วิภาคสรรพนาม (สรรพนามแยกฝ่าย)","นิยมสรรพนาม (ชี้เฉพาะ)","อนิยมสรรพนาม","ประพันธสรรพนาม"]', 0, 'คำว่า ต่าง, บ้าง, กัน ที่ใช้แยกฝ่ายหรือแสดงกริยาร่วมกันเป็นวิภาคสรรพนาม', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["ชนิดของคำ: คำสรรพนาม (หมวดที่ 79)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_080', 'thai', 'ภาษาไทย', 'Gifted', 3, 'การใช้ระดับภาษา (หมวดที่ 80)', 'ข้อความใดใช้ภาษา ระดับทางการ ได้อย่างถูกต้องเหมาะสมที่สุด (ข้อที่ 80)', '["โรงเรียนขอเชิญผู้ปกครองเข้าร่วมการประชุมใหญ่สามัญประจำปี","คุณพ่อคุณแม่รีบๆ มาคุยกันที่โรงเรียนนะ","พวกเราจัดงานประชุมใหญ่โตมากเชิญมาดู","ขอให้ทุกคนมาพร้อมหน้าพร้อมตากันที่โรงเรียน"]', 0, 'ใช้ถ้อยคำสุภาพ แบบแผน เป็นทางการและกะทัดรัด', 'สังเกตโครงสร้างและหลักภาษาไทย', 'ท่องจำกฎเกณฑ์ไวยากรณ์', '["การใช้ระดับภาษา (หมวดที่ 80)","Gifted"]');
