INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_001', 'social', 'สังคมศึกษา', 'Regular', 2, 'ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 1)', 'สมเด็จพระนเรศวรมหาราชทรงกระทำยุทธหัตถีมีชัยชนะเหนือพระมหาอุปราชา ณ ตำบลใด (คำถามที่ 1)', '["ตำบลหนองสาหร่าย เมืองสุพรรณบุรี","ตำบลดอนเจดีย์ เมืองกาญจนบุรี","ทุ่งมะขามหย่อง พระนครศรีอยุธยา","ตำบลบางแก้ว เมืองราชบุรี"]', 0, 'สงครามยุทธหัตถี พ.ศ. 2135 เกิดขึ้น ณ ตำบลหนองสาหร่าย เมืองสุพรรณบุรี', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 1)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_002', 'social', 'สังคมศึกษา', 'Gifted', 3, 'เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 2)', 'ภาวะ เงินเฟ้อ (Inflation) ส่งผลกระทบต่อกลุ่มบุคคลใดมากที่สุดในทางลบ (คำถามที่ 2)', '["ผู้มีรายได้ประจำและลูกจ้างกินเงินเดือนคงที่","พ่อค้าและนักธุรกิจขายสินค้า","ลูกหนี้ที่กู้ยืมเงิน","เจ้าของอสังหาริมทรัพย์"]', 0, 'เงินเฟ้อทำให้ข้าวของแพงขึ้น อำนาจซื้อของคนเงินเดือนคงที่ลดลงมากที่สุด', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 2)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_003', 'social', 'สังคมศึกษา', 'Regular', 1, 'ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 3)', 'ประเทศไทยใช้เวลามาตรฐานตามเส้นเมริเดียนลองจิจูดที่เท่าใด ซึ่งเร็วกว่าเวลาปานกลางกรีนิชกี่ชั่วโมง (คำถามที่ 3)', '["ลองจิจูด 105 องศาตะวันออก เร็วกว่า 7 ชั่วโมง (UTC+7)","ลองจิจูด 100 องศาตะวันออก เร็วกว่า 6 ชั่วโมง","ลองจิจูด 90 องศา เร็วกว่า 5 ชั่วโมง","ลองจิจูด 120 องศา เร็วกว่า 8 ชั่วโมง"]', 0, 'ไทยใช้เวลามาตรฐานที่เส้น 105°E (ผ่าน จ.อุบลราชธานี) เร็วกว่ากรีนิช 7 ชม.', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 3)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_004', 'social', 'สังคมศึกษา', 'Gifted', 2, 'พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 4)', 'วันสำคัญทางพระพุทธศาสนาวันใดที่มีเหตุการณ์ จาตุรงคสันนิบาต (พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย) (คำถามที่ 4)', '["วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3)","วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6)","วันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8)","วันอัฏฐมีบูชา"]', 0, 'วันมาฆบูชา มีเหตุการณ์อัศจรรย์ 4 ประการ พระพุทธเจ้าทรงแสดงโอวาทปาติโมกข์', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 4)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_005', 'social', 'สังคมศึกษา', 'Regular', 3, 'หน้าที่พลเมือง: กฎหมายแพ่งและอาญา (ชุดที่ 5)', 'การกระทำผิดในข้อใดจัดเป็น ความผิดทางอาญา ที่มีโทษถึงขั้นจำคุกหรือปรับต่อรัฐ (คำถามที่ 5)', '["การลักทรัพย์หรือทำร้ายร่างกายผู้อื่น","การผิดสัญญาเช่าซื้อบ้าน","การไม่ชำระหนี้เงินกู้ตามกำหนด","การละเมิดสิทธิบัตรทางการค้า"]', 0, 'ลักทรัพย์และทำร้ายร่างกายเป็นความผิดทางอาญา มีโทษปรับ กักขัง จำคุก ประหารชีวิต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: กฎหมายแพ่งและอาญา (ชุดที่ 5)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_006', 'social', 'สังคมศึกษา', 'Gifted', 1, 'ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 6)', 'สนธิสัญญาเบาว์ริงที่ทำขึ้นในสมัยรัชกาลที่ 4 ส่งผลให้เกิดการเปลี่ยนแปลงทางเศรษฐกิจของไทยอย่างไร (คำถามที่ 6)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มใช้เงินกระดาษธนบัตรครั้งแรก","ยกเลิกภาษีอากรทั้งหมด","ห้ามต่างชาติเข้ามาค้าขายในไทย"]', 0, 'ทำให้ไทยเข้าสู่ระบบการค้าเสรี ยกเลิกการผูกขาด และกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 6)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_007', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 7)', 'แก๊สเรือนกระจกชนิดใดที่เกิดจากการทำเกษตรกรรม การทำนาข้าว และการปศุสัตว์เป็นหลัก (คำถามที่ 7)', '["แก๊สมีเทน (Methane - CH4)","แก๊สคาร์บอนมอนอกไซด์","แก๊สซัลเฟอร์ไดออกไซด์","แก๊สคลอโรฟลูออโรคาร์บอน (CFC)"]', 0, 'การหมักหมมในนาข้าวและการย่อยอาหารของสัตว์เคี้ยวเอื้องปล่อยแก๊สมีเทนปริมาณมหาศาล', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 7)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_008', 'social', 'สังคมศึกษา', 'Gifted', 3, 'หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 8)', 'องค์กรอิสระตามรัฐธรรมนูญองค์กรใดทำหน้าที่ตรวจสอบการทุจริตประพฤติมิชอบของเจ้าหน้าที่รัฐ (คำถามที่ 8)', '["คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติ (ป.ป.ช.)","คณะกรรมการการเลือกตั้ง (กกต.)","ผู้ตรวจการแผ่นดิน","ศาลปกครอง"]', 0, 'ป.ป.ช. มีหน้าที่ไต่สวนและดำเนินคดีผู้ดำรงตำแหน่งทางการเมืองและเจ้าหน้าที่รัฐที่ทุจริต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 8)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_009', 'social', 'สังคมศึกษา', 'Regular', 1, 'วัฒนธรรมและประเพณีไทย (ชุดที่ 9)', 'ประเพณี ไหลเรือไฟ และ ผีตาโขน เป็นประเพณีที่มีชื่อเสียงของจังหวัดใดในภาคอีสานตามลำดับ (คำถามที่ 9)', '["จังหวัดนครพนม และ จังหวัดเลย","จังหวัดอุบลราชธานี และ จังหวัดยโสธร","จังหวัดขอนแก่น และ จังหวัดอุดรธานี","จังหวัดหนองคาย และ จังหวัดสุรินทร์"]', 0, 'ไหลเรือไฟจัดที่นครพนมในวันออกพรรษา ส่วนผีตาโขนจัดที่ อ.ด่านซ้าย จ.เลย', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["วัฒนธรรมและประเพณีไทย (ชุดที่ 9)","Regular"]');
