INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_016', 'social', 'สังคมศึกษา', 'Gifted', 2, 'ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 16)', 'สนธิสัญญาเบาว์ริงที่ทำขึ้นในสมัยรัชกาลที่ 4 ส่งผลให้เกิดการเปลี่ยนแปลงทางเศรษฐกิจของไทยอย่างไร (คำถามที่ 16)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มใช้เงินกระดาษธนบัตรครั้งแรก","ยกเลิกภาษีอากรทั้งหมด","ห้ามต่างชาติเข้ามาค้าขายในไทย"]', 0, 'ทำให้ไทยเข้าสู่ระบบการค้าเสรี ยกเลิกการผูกขาด และกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 16)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_017', 'social', 'สังคมศึกษา', 'Regular', 3, 'ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 17)', 'แก๊สเรือนกระจกชนิดใดที่เกิดจากการทำเกษตรกรรม การทำนาข้าว และการปศุสัตว์เป็นหลัก (คำถามที่ 17)', '["แก๊สมีเทน (Methane - CH4)","แก๊สคาร์บอนมอนอกไซด์","แก๊สซัลเฟอร์ไดออกไซด์","แก๊สคลอโรฟลูออโรคาร์บอน (CFC)"]', 0, 'การหมักหมมในนาข้าวและการย่อยอาหารของสัตว์เคี้ยวเอื้องปล่อยแก๊สมีเทนปริมาณมหาศาล', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 17)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_018', 'social', 'สังคมศึกษา', 'Gifted', 1, 'หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 18)', 'องค์กรอิสระตามรัฐธรรมนูญองค์กรใดทำหน้าที่ตรวจสอบการทุจริตประพฤติมิชอบของเจ้าหน้าที่รัฐ (คำถามที่ 18)', '["คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติ (ป.ป.ช.)","คณะกรรมการการเลือกตั้ง (กกต.)","ผู้ตรวจการแผ่นดิน","ศาลปกครอง"]', 0, 'ป.ป.ช. มีหน้าที่ไต่สวนและดำเนินคดีผู้ดำรงตำแหน่งทางการเมืองและเจ้าหน้าที่รัฐที่ทุจริต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 18)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_019', 'social', 'สังคมศึกษา', 'Regular', 2, 'วัฒนธรรมและประเพณีไทย (ชุดที่ 19)', 'ประเพณี ไหลเรือไฟ และ ผีตาโขน เป็นประเพณีที่มีชื่อเสียงของจังหวัดใดในภาคอีสานตามลำดับ (คำถามที่ 19)', '["จังหวัดนครพนม และ จังหวัดเลย","จังหวัดอุบลราชธานี และ จังหวัดยโสธร","จังหวัดขอนแก่น และ จังหวัดอุดรธานี","จังหวัดหนองคาย และ จังหวัดสุรินทร์"]', 0, 'ไหลเรือไฟจัดที่นครพนมในวันออกพรรษา ส่วนผีตาโขนจัดที่ อ.ด่านซ้าย จ.เลย', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["วัฒนธรรมและประเพณีไทย (ชุดที่ 19)","Regular"]');
