INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_028', 'social', 'สังคมศึกษา', 'Gifted', 2, 'หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 28)', 'องค์กรอิสระตามรัฐธรรมนูญองค์กรใดทำหน้าที่ตรวจสอบการทุจริตประพฤติมิชอบของเจ้าหน้าที่รัฐ (คำถามที่ 28)', '["คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติ (ป.ป.ช.)","คณะกรรมการการเลือกตั้ง (กกต.)","ผู้ตรวจการแผ่นดิน","ศาลปกครอง"]', 0, 'ป.ป.ช. มีหน้าที่ไต่สวนและดำเนินคดีผู้ดำรงตำแหน่งทางการเมืองและเจ้าหน้าที่รัฐที่ทุจริต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 28)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_029', 'social', 'สังคมศึกษา', 'Regular', 3, 'วัฒนธรรมและประเพณีไทย (ชุดที่ 29)', 'ประเพณี ไหลเรือไฟ และ ผีตาโขน เป็นประเพณีที่มีชื่อเสียงของจังหวัดใดในภาคอีสานตามลำดับ (คำถามที่ 29)', '["จังหวัดนครพนม และ จังหวัดเลย","จังหวัดอุบลราชธานี และ จังหวัดยโสธร","จังหวัดขอนแก่น และ จังหวัดอุดรธานี","จังหวัดหนองคาย และ จังหวัดสุรินทร์"]', 0, 'ไหลเรือไฟจัดที่นครพนมในวันออกพรรษา ส่วนผีตาโขนจัดที่ อ.ด่านซ้าย จ.เลย', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["วัฒนธรรมและประเพณีไทย (ชุดที่ 29)","Regular"]');
