INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_031', 'social', 'สังคมศึกษา', 'Regular', 2, 'ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 31)', 'สมเด็จพระนเรศวรมหาราชทรงกระทำยุทธหัตถีมีชัยชนะเหนือพระมหาอุปราชา ณ ตำบลใด (คำถามที่ 31)', '["ตำบลหนองสาหร่าย เมืองสุพรรณบุรี","ตำบลดอนเจดีย์ เมืองกาญจนบุรี","ทุ่งมะขามหย่อง พระนครศรีอยุธยา","ตำบลบางแก้ว เมืองราชบุรี"]', 0, 'สงครามยุทธหัตถี พ.ศ. 2135 เกิดขึ้น ณ ตำบลหนองสาหร่าย เมืองสุพรรณบุรี', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 31)","Regular"]');
