INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_040', 'social', 'สังคมศึกษา', 'Gifted', 2, 'ประชาคมอาเซียน: กฎบัตรอาเซียน (ชุดที่ 40)', 'คำขวัญ (Motto) ประจำประชาคมอาเซียนคือข้อใด (คำถามที่ 40)', '["One Vision, One Identity, One Community (หนึ่งวิสัยทัศน์ หนึ่งอัตลักษณ์ หนึ่งประชาคม)","Unity in Diversity","Together We Can","Peace and Prosperity for All"]', 0, 'คำขวัญอาเซียนคือ หนึ่งวิสัยทัศน์ หนึ่งอัตลักษณ์ หนึ่งประชาคม', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประชาคมอาเซียน: กฎบัตรอาเซียน (ชุดที่ 40)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_041', 'social', 'สังคมศึกษา', 'Regular', 3, 'ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 41)', 'สมเด็จพระนเรศวรมหาราชทรงกระทำยุทธหัตถีมีชัยชนะเหนือพระมหาอุปราชา ณ ตำบลใด (คำถามที่ 41)', '["ตำบลหนองสาหร่าย เมืองสุพรรณบุรี","ตำบลดอนเจดีย์ เมืองกาญจนบุรี","ทุ่งมะขามหย่อง พระนครศรีอยุธยา","ตำบลบางแก้ว เมืองราชบุรี"]', 0, 'สงครามยุทธหัตถี พ.ศ. 2135 เกิดขึ้น ณ ตำบลหนองสาหร่าย เมืองสุพรรณบุรี', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สมเด็จพระนเรศวรมหาราช (ชุดที่ 41)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_042', 'social', 'สังคมศึกษา', 'Gifted', 1, 'เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 42)', 'ภาวะ เงินเฟ้อ (Inflation) ส่งผลกระทบต่อกลุ่มบุคคลใดมากที่สุดในทางลบ (คำถามที่ 42)', '["ผู้มีรายได้ประจำและลูกจ้างกินเงินเดือนคงที่","พ่อค้าและนักธุรกิจขายสินค้า","ลูกหนี้ที่กู้ยืมเงิน","เจ้าของอสังหาริมทรัพย์"]', 0, 'เงินเฟ้อทำให้ข้าวของแพงขึ้น อำนาจซื้อของคนเงินเดือนคงที่ลดลงมากที่สุด', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 42)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_043', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 43)', 'ประเทศไทยใช้เวลามาตรฐานตามเส้นเมริเดียนลองจิจูดที่เท่าใด ซึ่งเร็วกว่าเวลาปานกลางกรีนิชกี่ชั่วโมง (คำถามที่ 43)', '["ลองจิจูด 105 องศาตะวันออก เร็วกว่า 7 ชั่วโมง (UTC+7)","ลองจิจูด 100 องศาตะวันออก เร็วกว่า 6 ชั่วโมง","ลองจิจูด 90 องศา เร็วกว่า 5 ชั่วโมง","ลองจิจูด 120 องศา เร็วกว่า 8 ชั่วโมง"]', 0, 'ไทยใช้เวลามาตรฐานที่เส้น 105°E (ผ่าน จ.อุบลราชธานี) เร็วกว่ากรีนิช 7 ชม.', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 43)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_044', 'social', 'สังคมศึกษา', 'Gifted', 3, 'พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 44)', 'วันสำคัญทางพระพุทธศาสนาวันใดที่มีเหตุการณ์ จาตุรงคสันนิบาต (พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย) (คำถามที่ 44)', '["วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3)","วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6)","วันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8)","วันอัฏฐมีบูชา"]', 0, 'วันมาฆบูชา มีเหตุการณ์อัศจรรย์ 4 ประการ พระพุทธเจ้าทรงแสดงโอวาทปาติโมกข์', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 44)","Gifted"]');
