INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_052', 'social', 'สังคมศึกษา', 'Gifted', 2, 'เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 52)', 'ภาวะ เงินเฟ้อ (Inflation) ส่งผลกระทบต่อกลุ่มบุคคลใดมากที่สุดในทางลบ (คำถามที่ 52)', '["ผู้มีรายได้ประจำและลูกจ้างกินเงินเดือนคงที่","พ่อค้าและนักธุรกิจขายสินค้า","ลูกหนี้ที่กู้ยืมเงิน","เจ้าของอสังหาริมทรัพย์"]', 0, 'เงินเฟ้อทำให้ข้าวของแพงขึ้น อำนาจซื้อของคนเงินเดือนคงที่ลดลงมากที่สุด', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["เศรษฐศาสตร์: สหกรณ์และเงินเฟ้อ (ชุดที่ 52)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_053', 'social', 'สังคมศึกษา', 'Regular', 3, 'ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 53)', 'ประเทศไทยใช้เวลามาตรฐานตามเส้นเมริเดียนลองจิจูดที่เท่าใด ซึ่งเร็วกว่าเวลาปานกลางกรีนิชกี่ชั่วโมง (คำถามที่ 53)', '["ลองจิจูด 105 องศาตะวันออก เร็วกว่า 7 ชั่วโมง (UTC+7)","ลองจิจูด 100 องศาตะวันออก เร็วกว่า 6 ชั่วโมง","ลองจิจูด 90 องศา เร็วกว่า 5 ชั่วโมง","ลองจิจูด 120 องศา เร็วกว่า 8 ชั่วโมง"]', 0, 'ไทยใช้เวลามาตรฐานที่เส้น 105°E (ผ่าน จ.อุบลราชธานี) เร็วกว่ากรีนิช 7 ชม.', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์: เวลาและเส้นเมริเดียน (ชุดที่ 53)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_054', 'social', 'สังคมศึกษา', 'Gifted', 1, 'พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 54)', 'วันสำคัญทางพระพุทธศาสนาวันใดที่มีเหตุการณ์ จาตุรงคสันนิบาต (พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย) (คำถามที่ 54)', '["วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3)","วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6)","วันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8)","วันอัฏฐมีบูชา"]', 0, 'วันมาฆบูชา มีเหตุการณ์อัศจรรย์ 4 ประการ พระพุทธเจ้าทรงแสดงโอวาทปาติโมกข์', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 54)","Gifted"]');
