INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_056', 'social', 'สังคมศึกษา', 'Gifted', 3, 'ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 56)', 'สนธิสัญญาเบาว์ริงที่ทำขึ้นในสมัยรัชกาลที่ 4 ส่งผลให้เกิดการเปลี่ยนแปลงทางเศรษฐกิจของไทยอย่างไร (คำถามที่ 56)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มใช้เงินกระดาษธนบัตรครั้งแรก","ยกเลิกภาษีอากรทั้งหมด","ห้ามต่างชาติเข้ามาค้าขายในไทย"]', 0, 'ทำให้ไทยเข้าสู่ระบบการค้าเสรี ยกเลิกการผูกขาด และกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 56)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_057', 'social', 'สังคมศึกษา', 'Regular', 1, 'ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 57)', 'แก๊สเรือนกระจกชนิดใดที่เกิดจากการทำเกษตรกรรม การทำนาข้าว และการปศุสัตว์เป็นหลัก (คำถามที่ 57)', '["แก๊สมีเทน (Methane - CH4)","แก๊สคาร์บอนมอนอกไซด์","แก๊สซัลเฟอร์ไดออกไซด์","แก๊สคลอโรฟลูออโรคาร์บอน (CFC)"]', 0, 'การหมักหมมในนาข้าวและการย่อยอาหารของสัตว์เคี้ยวเอื้องปล่อยแก๊สมีเทนปริมาณมหาศาล', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 57)","Regular"]');
