INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_064', 'social', 'สังคมศึกษา', 'Gifted', 2, 'พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 64)', 'วันสำคัญทางพระพุทธศาสนาวันใดที่มีเหตุการณ์ จาตุรงคสันนิบาต (พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย) (คำถามที่ 64)', '["วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3)","วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6)","วันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8)","วันอัฏฐมีบูชา"]', 0, 'วันมาฆบูชา มีเหตุการณ์อัศจรรย์ 4 ประการ พระพุทธเจ้าทรงแสดงโอวาทปาติโมกข์', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["พระพุทธศาสนา: วันสำคัญทางศาสนา (ชุดที่ 64)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_065', 'social', 'สังคมศึกษา', 'Regular', 3, 'หน้าที่พลเมือง: กฎหมายแพ่งและอาญา (ชุดที่ 65)', 'การกระทำผิดในข้อใดจัดเป็น ความผิดทางอาญา ที่มีโทษถึงขั้นจำคุกหรือปรับต่อรัฐ (คำถามที่ 65)', '["การลักทรัพย์หรือทำร้ายร่างกายผู้อื่น","การผิดสัญญาเช่าซื้อบ้าน","การไม่ชำระหนี้เงินกู้ตามกำหนด","การละเมิดสิทธิบัตรทางการค้า"]', 0, 'ลักทรัพย์และทำร้ายร่างกายเป็นความผิดทางอาญา มีโทษปรับ กักขัง จำคุก ประหารชีวิต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: กฎหมายแพ่งและอาญา (ชุดที่ 65)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_066', 'social', 'สังคมศึกษา', 'Gifted', 1, 'ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 66)', 'สนธิสัญญาเบาว์ริงที่ทำขึ้นในสมัยรัชกาลที่ 4 ส่งผลให้เกิดการเปลี่ยนแปลงทางเศรษฐกิจของไทยอย่างไร (คำถามที่ 66)', '["ยกเลิกการค้าผูกขาดของพระคลังสินค้า และเก็บภาษีร้อยชักสาม","เริ่มใช้เงินกระดาษธนบัตรครั้งแรก","ยกเลิกภาษีอากรทั้งหมด","ห้ามต่างชาติเข้ามาค้าขายในไทย"]', 0, 'ทำให้ไทยเข้าสู่ระบบการค้าเสรี ยกเลิกการผูกขาด และกำหนดภาษีศุลกากร 3% (ร้อยชักสาม)', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ประวัติศาสตร์: สนธิสัญญาเบาว์ริง (ชุดที่ 66)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_067', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 67)', 'แก๊สเรือนกระจกชนิดใดที่เกิดจากการทำเกษตรกรรม การทำนาข้าว และการปศุสัตว์เป็นหลัก (คำถามที่ 67)', '["แก๊สมีเทน (Methane - CH4)","แก๊สคาร์บอนมอนอกไซด์","แก๊สซัลเฟอร์ไดออกไซด์","แก๊สคลอโรฟลูออโรคาร์บอน (CFC)"]', 0, 'การหมักหมมในนาข้าวและการย่อยอาหารของสัตว์เคี้ยวเอื้องปล่อยแก๊สมีเทนปริมาณมหาศาล', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["ภูมิศาสตร์สิ่งแวดล้อม: ภาวะโลกร้อน (ชุดที่ 67)","Regular"]');
