INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_079', 'social', 'สังคมศึกษา', 'Regular', 2, 'วัฒนธรรมและประเพณีไทย (ชุดที่ 79)', 'ประเพณี ไหลเรือไฟ และ ผีตาโขน เป็นประเพณีที่มีชื่อเสียงของจังหวัดใดในภาคอีสานตามลำดับ (คำถามที่ 79)', '["จังหวัดนครพนม และ จังหวัดเลย","จังหวัดอุบลราชธานี และ จังหวัดยโสธร","จังหวัดขอนแก่น และ จังหวัดอุดรธานี","จังหวัดหนองคาย และ จังหวัดสุรินทร์"]', 0, 'ไหลเรือไฟจัดที่นครพนมในวันออกพรรษา ส่วนผีตาโขนจัดที่ อ.ด่านซ้าย จ.เลย', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["วัฒนธรรมและประเพณีไทย (ชุดที่ 79)","Regular"]');
