INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_088', 'social', 'สังคมศึกษา', 'Gifted', 2, 'หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 88)', 'องค์กรอิสระตามรัฐธรรมนูญองค์กรใดทำหน้าที่ตรวจสอบการทุจริตประพฤติมิชอบของเจ้าหน้าที่รัฐ (คำถามที่ 88)', '["คณะกรรมการป้องกันและปราบปรามการทุจริตแห่งชาติ (ป.ป.ช.)","คณะกรรมการการเลือกตั้ง (กกต.)","ผู้ตรวจการแผ่นดิน","ศาลปกครอง"]', 0, 'ป.ป.ช. มีหน้าที่ไต่สวนและดำเนินคดีผู้ดำรงตำแหน่งทางการเมืองและเจ้าหน้าที่รัฐที่ทุจริต', 'วิเคราะห์บริบททางประวัติศาสตร์และสังคม', 'เชื่อมโยงเหตุการณ์สำคัญ', '["หน้าที่พลเมือง: รัฐธรรมนูญและองค์กรอิสระ (ชุดที่ 88)","Gifted"]');
